INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6035', 'CS', '6035', 'Introduction to Information Security', 3, 1, 'CS', 'The big-picture view of information security: policy, cryptography, network and software security, and the human factors behind them.', '["security","foundations"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6150', 'CS', '6150', 'Computing for Good', 3, 0, 'CS', 'Project-based course on applying computing to social-good problems with real nonprofit and government partners.', '["social impact","project"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6200', 'CS', '6200', 'Introduction to Operating Systems', 3, 1, 'CS', 'Processes, threads, scheduling, synchronization, memory management, file systems, and OS design through hands-on projects.', '["systems","operating systems","C"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6210', 'CS', '6210', 'Advanced Operating Systems', 3, 1, 'CS', 'Graduate-level treatment of distributed systems, concurrency, virtualization, and the papers that shaped modern OS design.', '["systems","distributed","research papers"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6211', 'CS', '6211', 'System Design for Cloud Computing', 3, 1, 'CS', 'Designing scalable cloud services: containers, orchestration, fault tolerance, and the trade-offs behind real architectures.', '["systems","cloud","distributed"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6238', 'CS', '6238', 'Secure Computer Systems', 3, 1, 'OMS Cybersecurity', 'Operating-system and architecture level security: access control, isolation, virtualization security, and trusted computing.', '["security","systems"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6250', 'CS', '6250', 'Computer Networks', 3, 1, 'OMS Cybersecurity', 'From sockets up: routing, congestion control, naming, SDN, and the measurement work behind today''s network protocols.', '["networking","systems"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6260', 'CS', '6260', 'Applied Cryptography', 3, 1, 'OMS Cybersecurity', 'How cryptographic primitives are used in practice: block ciphers, hashing, public key infrastructure, and protocol design.', '["security","cryptography","math"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6261', 'CS', '6261', 'Security Operations and Incident Response', 3, 0, 'OMS Cybersecurity', 'Running a security program day to day: detection engineering, log analysis, incident handling, and forensics workflow.', '["security","blue team","operations"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6262', 'CS', '6262', 'Network Security', 3, 1, 'CS', 'Attacks and defenses across the network stack, from ARP and DNS abuse to TLS, firewalls, and intrusion detection.', '["security","networking"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6263', 'CS', '6263', 'Introduction to Cyber-Physical Systems Security', 3, 1, 'CS', 'Security of systems that touch the physical world: industrial control, automotive, medical devices, and sensor networks.', '["security","embedded","robotics"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6264', 'CS', '6264', 'Information Security Lab: System and Network Defenses', 3, 1, 'OMS Cybersecurity', 'Hands-on lab hardening hosts and networks: auditing, monitoring, exploitation, and defense in depth.', '["security","lab","networking"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6265', 'CS', '6265', 'Information Security Lab', 3, 0, 'OMS Cybersecurity', 'Open-ended security lab course focused on practical exploitation and defense in realistic environments.', '["security","lab"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6271', 'CS', '6271', 'Cybersecurity of Drones', 3, 0, 'OMS Cybersecurity', 'Threat models and defenses for unmanned aerial systems, including wireless links, GPS spoofing, and autonomy risks.', '["security","embedded","robotics"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6290', 'CS', '6290', 'High Performance Computer Architecture', 3, 1, 'CS', 'Pipelining, caches, out-of-order execution, multiprocessors, and memory systems — how processors really get fast.', '["architecture","systems","hardware"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6291', 'CS', '6291', 'Embedded Systems Optimization', 3, 1, 'CS', 'Making software fast and small on constrained hardware: compilers, profiling, code generation, and hardware-aware design.', '["embedded","systems","performance"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6300', 'CS', '6300', 'Software Development Process', 3, 1, 'CS', 'Software engineering as a discipline: requirements, design, testing, UML, and team process on a semester-long project.', '["software engineering","project"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6310', 'CS', '6310', 'Software Architecture and Design', 3, 1, 'CS', 'Architectural styles, quality attributes, and design reasoning for large systems, with an emphasis on real-world trade-offs.', '["software engineering","architecture"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6340', 'CS', '6340', 'Software Analysis', 3, 1, 'CS', 'Static and dynamic program analysis: dataflow, symbolic execution, testing, and bug finding, with tool-building assignments.', '["software engineering","programming languages","testing"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6400', 'CS', '6400', 'Database Systems Concepts and Design', 3, 1, 'CS', 'Relational modeling, SQL, transactions, indexing, and database design for application developers.', '["databases","systems"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6422', 'CS', '6422', 'Database System Implementation', 3, 1, 'CS', 'Building the inside of a database: storage, buffer management, query execution, and recovery, usually in a large project.', '["databases","systems","project"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6435', 'CS', '6435', 'Digital Health Equity', 3, 1, 'CS', 'How digital health tools widen or narrow health disparities, and how to design and evaluate them more equitably.', '["health","HCI","policy"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6440', 'CS', '6440', 'Introduction to Health Informatics', 3, 1, 'CS', 'Data, standards, and systems in healthcare: EHRs, interoperability, clinical decision support, and informatics methods.', '["health","data","HCI"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6457', 'CS', '6457', 'Video Game Design', 3, 1, 'CS', 'Game design theory and practice: mechanics, level design, playtesting, and building a playable game in a team.', '["games","graphics","HCI","project"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6460', 'CS', '6460', 'Educational Technology', 3, 1, 'CS', 'Learning sciences meets software: designing, building, and evaluating technology that helps people learn.', '["education","HCI","project"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6475', 'CS', '6475', 'Computational Photography', 3, 1, 'CS', 'Cameras as computation: image formation, HDR, panorama stitching, and the algorithms behind modern photography.', '["graphics","vision","imaging"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6476', 'CS', '6476', 'Computer Vision', 3, 1, 'CS', 'Classical and learned vision: filtering, features, geometry, stereo, recognition, and deep models for images.', '["vision","machine learning","robotics"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6491', 'CS', '6491', 'Foundations of Computer Graphics', 3, 1, 'CS', 'The graphics pipeline from math to pixels: transformations, rasterization, shading, and ray tracing.', '["graphics","math"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6515', 'CS', '6515', 'Introduction to Graduate Algorithms', 3, 1, 'CS', 'Dynamic programming, graph algorithms, NP-completeness, randomized algorithms, and linear programming at graduate pace.', '["algorithms","theory","math"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6601', 'CS', '6601', 'Artificial Intelligence', 3, 1, 'CS', 'Search, constraint satisfaction, probabilistic reasoning, planning, and learning — the breadth course for AI.', '["AI","machine learning","search"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6603', 'CS', '6603', 'AI, Ethics, and Society', 3, 1, 'CS', 'Ethical and policy questions raised by AI systems: bias, accountability, privacy, and governance, with case studies.', '["AI","ethics","policy"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6675', 'CS', '6675', 'Advanced Internet Systems and Applications', 3, 1, 'CS', 'How large internet services are built: caching, data centers, peer-to-peer, and case studies of real systems.', '["systems","distributed","cloud"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6747', 'CS', '6747', 'Advanced Malware Analysis', 3, 0, 'OMS Cybersecurity', 'Reverse engineering malicious software: static and dynamic analysis, evasion techniques, and detection strategy.', '["security","reverse engineering","lab"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6750', 'CS', '6750', 'Human-Computer Interaction', 3, 1, 'CS', 'The core HCI course: design principles, prototyping, usability evaluation, and user research methods.', '["HCI","design","research methods"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-6795', 'CS', '6795', 'Introduction to Cognitive Science', 3, 1, 'CS', 'Computation, representation, and mind: the cognitive science foundations that inform AI and HCI.', '["cognitive science","AI","theory"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-7210', 'CS', '7210', 'Distributed Computing', 3, 1, 'CS', 'Consensus, replication, time and ordering, fault tolerance, and the theory behind distributed systems.', '["distributed","systems","theory"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-7240', 'CS', '7240', 'Modern Internet Research Methods', 3, 0, 'CS', 'Measurement and experimentation on internet-scale systems, including data collection, ethics, and analysis.', '["networking","research methods","data"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-7280', 'CS', '7280', 'Network Science', 3, 1, 'CS', 'Graph structure and dynamics in real networks: centrality, communities, cascades, and epidemic models.', '["networks","data","math"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-7295', 'CS', '7295', 'GPU Hardware and Software', 3, 1, 'CS', 'GPU architecture and programming: SIMT execution, memory hierarchies, CUDA, and performance tuning.', '["architecture","performance","hardware"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-7400', 'CS', '7400', 'Introduction to Quantum Computing', 3, 1, 'CS', 'Qubits, gates, entanglement, and the algorithms (Grover, Shor) that make quantum computing interesting.', '["quantum","theory","math"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-7470', 'CS', '7470', 'Mobile and Ubiquitous Computing', 3, 1, 'CS', 'Mobile systems and context-aware applications: sensing, energy, interaction, and prototyping for devices in the world.', '["mobile","HCI","systems"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-7496', 'CS', '7496', 'Computer Animation', 3, 1, 'CS', 'Keyframing, skinning, motion capture, physics-based animation, and the math behind believable movement.', '["graphics","animation","math"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-7632', 'CS', '7632', 'Game AI', 3, 1, 'CS', 'Agents that play and design games: search, planning, procedural content generation, and player modeling.', '["AI","games","machine learning"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-7637', 'CS', '7637', 'Knowledge-Based AI', 3, 1, 'CS', 'Symbolic AI: knowledge representation, reasoning, analogy, and cognitive architectures for problem solving.', '["AI","cognitive science","reasoning"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-7638', 'CS', '7638', 'Robotics: AI Techniques', 3, 1, 'CS', 'Localization, mapping, SLAM, planning, and control for robots, with simulation-based projects.', '["robotics","AI","project"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-7639', 'CS', '7639', 'Cyber-Physical Design and Analysis', 3, 1, 'CS', 'Modeling and verifying systems that mix computation and physics, from controllers to autonomous vehicles.', '["robotics","embedded","math"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-7641', 'CS', '7641', 'Machine Learning', 3, 1, 'CS', 'Supervised and unsupervised learning in depth: decision trees, boosting, SVM, clustering, and reinforcement learning.', '["machine learning","AI","math"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-7642', 'CS', '7642', 'Reinforcement Learning', 3, 1, 'CS', 'MDPs, dynamic programming, temporal-difference learning, policy gradients, and exploration strategies.', '["machine learning","AI","math"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-7643', 'CS', '7643', 'Deep Learning', 3, 1, 'CS', 'Neural network fundamentals through modern architectures: CNNs, RNNs, transformers, and training at scale.', '["machine learning","AI","deep learning"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-7646', 'CS', '7646', 'Machine Learning for Trading', 3, 1, 'CS', 'Applying ML to markets: time series, portfolio construction, and backtesting with realistic data and costs.', '["machine learning","finance","data"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-7650', 'CS', '7650', 'Natural Language', 3, 1, 'CS', 'Language processing from n-grams to neural models: parsing, embeddings, sequence models, and LLM-era techniques.', '["NLP","machine learning","AI"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-7711', 'CS', '7711', 'Health Sensing and Interventions', 3, 1, 'CS', 'Sensing human physiology and behavior, and turning that signal into interventions that improve health outcomes.', '["health","sensing","HCI"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-8803-O08', 'CS', '8803-O08', 'Compilers: Theory and Practice', 3, 1, 'CS', 'Lexing, parsing, type checking, optimization, and code generation, with a compiler built from scratch.', '["compilers","programming languages","systems"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-8803-O15', 'CS', '8803-O15', 'Introduction to Computer Law', 3, 0, 'CS', 'Legal frameworks that shape software: intellectual property, privacy, contracts, and liability for computing systems.', '["law","policy"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-8803-O17', 'CS', '8803-O17', 'Global Entrepreneurship', 3, 0, 'CS', 'Turning technical ideas into ventures: customer discovery, business models, and pitching in an international context.', '["entrepreneurship","business"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-8803-O20', 'CS', '8803-O20', 'Quantum Hardware', 3, 0, 'CS', 'How quantum computers are physically built: qubit technologies, control electronics, and error correction.', '["quantum","hardware"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-8803-O24', 'CS', '8803-O24', 'Introduction to Research', 3, 0, 'CS', 'How computing research works: reading papers critically, forming questions, and designing a small study.', '["research methods","theory"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-8803-O25', 'CS', '8803-O25', 'Advanced Wireless Networks', 3, 0, 'CS', 'Wireless PHY and MAC layers, cellular and WiFi evolution, mobility, and the measurement of real deployments.', '["networking","wireless","systems"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-8803-O27', 'CS', '8803-O27', 'Computer Graphics in the AI Era', 3, 0, 'CS', 'Neural rendering, generative image models, and how learned methods are reshaping the graphics pipeline.', '["graphics","AI","deep learning"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-8803-O34', 'CS', '8803-O34', 'Human Dimension of Cybersecurity', 3, 0, 'OMS Cybersecurity', 'People as the attack surface: usable security, social engineering, insider risk, and security culture.', '["security","HCI","psychology"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CS-8803-ORO', 'CS', '8803-ORO', 'Management and Leadership in Computing', 3, 0, 'CS', 'Technical leadership: running teams, communicating with stakeholders, and making decisions under uncertainty.', '["management","soft skills"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CSE-6220', 'CSE', '6220', 'Introduction to High-Performance Computing', 3, 1, 'CSE', 'Parallel algorithms and architectures: MPI, OpenMP, performance modeling, and scientific workloads at scale.', '["HPC","performance","systems"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CSE-6242', 'CSE', '6242', 'Data and Visual Analytics', 3, 1, 'OMS Analytics', 'The analytics stack end to end: data wrangling, scalable processing, visualization, and analytics pipelines.', '["data","visualization","machine learning","project"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CSE-6250', 'CSE', '6250', 'Big Data for Health Informatics', 3, 1, 'CSE', 'Scalable methods for health data: streaming pipelines, NoSQL, graph analytics, and privacy-aware analysis.', '["health","data","big data"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('CSE-6742', 'CSE', '6742', 'Modeling, Simulation, and Military Gaming', 3, 0, 'OMS Cybersecurity', 'Discrete-event and agent-based modeling applied to defense scenarios, wargaming, and analysis.', '["simulation","modeling","security"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('ECE-8843', 'ECE', '8843', 'Side-Channels and Their Role in Cybersecurity', 3, 0, 'OMS Cybersecurity', 'Extracting secrets from timing, power, and electromagnetic leakage, and the countermeasures that mitigate them.', '["security","hardware"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('INTA-6450', 'INTA', '6450', 'Data Analytics and Security', 3, 0, 'OMS Cybersecurity', 'Analytic tradecraft and data methods for security and intelligence problems, with a policy lens.', '["security","data","policy"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('ISYE-6402', 'ISYE', '6402', 'Time Series Analysis', 3, 0, 'OMS Analytics', 'ARIMA, state space models, and forecasting for temporal data, with applied analysis in R.', '["statistics","data","math"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('ISYE-6414', 'ISYE', '6414', 'Regression Analysis', 3, 0, 'OMS Analytics', 'Linear and generalized linear models: estimation, diagnostics, model selection, and inference.', '["statistics","data","math"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('ISYE-6420', 'ISYE', '6420', 'Bayesian Statistics', 3, 1, 'OMS Analytics', 'Priors, posteriors, MCMC, and hierarchical modeling, with computational work in R.', '["statistics","machine learning","math"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('ISYE-6501', 'ISYE', '6501', 'Introduction to Analytics Modeling', 3, 0, 'OMS Analytics', 'Broad survey of analytics models — regression, classification, clustering, optimization, simulation — with a practical focus.', '["data","machine learning","statistics"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('ISYE-6525', 'ISYE', '6525', 'Topics on High-Dimensional Data Analytics', 3, 0, 'OMS Analytics', 'Statistical methods for wide data: regularization, dimension reduction, and high-dimensional inference.', '["statistics","data","machine learning"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('ISYE-6644', 'ISYE', '6644', 'Simulation and Modeling for Engineering and Science', 3, 0, 'OMS Analytics', 'Random number generation, discrete-event simulation, input modeling, and output analysis.', '["simulation","statistics","math"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('ISYE-6669', 'ISYE', '6669', 'Deterministic Optimization', 3, 0, 'OMS Analytics', 'Linear, integer, and network optimization with modeling practice and solver-based assignments.', '["optimization","math","operations research"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('MGT-6311', 'MGT', '6311', 'Digital Marketing', 3, 0, 'OMS Analytics', 'Marketing in digital channels: analytics, customer journey, experimentation, and campaign strategy.', '["business","marketing","data"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('MGT-8813', 'MGT', '8813', 'Financial Modeling', 3, 0, 'OMS Analytics', 'Building financial models: valuation, forecasting, and spreadsheet engineering for decision making.', '["finance","business","modeling"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('PUBP-6725', 'PUBP', '6725', 'Information Security Policies', 3, 0, 'OMS Cybersecurity', 'How security policy is made and enforced: regulation, standards, incentives, and organizational governance.', '["security","policy"]');
INSERT INTO courses (id, subject, number, title, credits, foundational, admin, description, tags) VALUES ('PUBP-8823', 'PUBP', '8823', 'Geopolitics of Cybersecurity', 3, 0, 'OMS Cybersecurity', 'Cybersecurity as international relations: deterrence, attribution, norms, and state-backed threats.', '["security","policy","geopolitics"]');
